      extraWords: <EnglishAdvancedWord>[EnglishAdvancedWord("debate motion", "قضية المناظرة"), EnglishAdvancedWord("argument structure", "بنية الحجة"), EnglishAdvancedWord("opening argument", "حجة افتتاحية"), EnglishAdvancedWord("counterargument", "حجة مضادة"), EnglishAdvancedWord("rebuttal statement", "بيان تفنيد"), EnglishAdvancedWord("logical connection", "صلة منطقية"), EnglishAdvancedWord("relevant evidence", "دليل ذو صلة"), EnglishAdvancedWord("burden of proof", "عبء الإثبات"), EnglishAdvancedWord("general claim", "ادعاء عام"), EnglishAdvancedWord("debate format", "صيغة المناظرة"), EnglishAdvancedWord("speaking allocation", "وقت الكلام المخصص"), EnglishAdvancedWord("closing statement", "بيان ختامي"), EnglishAdvancedWord("acknowledge a limitation", "يقر بقيد"), EnglishAdvancedWord("challenge an assumption", "يتحدى افتراضًا"), EnglishAdvancedWord("reasoned response", "رد معلل"), EnglishAdvancedWord("intellectual honesty", "أمانة فكرية"), EnglishAdvancedWord("policy exception", "استثناء السياسة"), EnglishAdvancedWord("audience evaluation", "تقييم الجمهور"), EnglishAdvancedWord("argument strength", "قوة الحجة"), EnglishAdvancedWord("structured disagreement", "خلاف منظم"), EnglishAdvancedWord("defensible position", "موقف قابل للدفاع"), EnglishAdvancedWord("evidence quality", "جودة الدليل")],
